const transitions = {
  new: { pay: 'paid' },
  paid: { ship: 'shipped' },
  shipped: { deliver: 'delivered' }
};
function nextState(state, event) {
  const from = transitions[state] || {};
  return from[event] || state;
}
console.log(nextState('paid', 'ship'));

